		/** 
		 * Tests creating a new KYCProfile.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a KYCProfile");

			StringBuilder msg = new StringBuilder( "-- Failed to create a KYCProfile" );

			try {            
				KYCProfile entity = KYCProfileService.getKYCProfileInstance().createKYCProfile( generateNewEntity() );
				thePrimaryKey = entity.getKYCProfileId();
				LOGGER.info( "-- Successfully created a KYCProfile with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a KYCProfile. 
		 */
		public KYCProfile testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created KYCProfile" );

			KYCProfile entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read KYCProfile with primary key" );
			msg.append( thePrimaryKey );
			
			KYCProfileFetchOneSummary fetchOneSummary = new KYCProfileFetchOneSummary( thePrimaryKey );

			try {
				entity = KYCProfileService.getKYCProfileInstance().getKYCProfile( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found KYCProfile " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a KYCProfile.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a KYCProfile." );

			StringBuilder msg = new StringBuilder( "Failed to update a KYCProfile : " );        
			KYCProfile entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created KYCProfile." );

				// for use later on...
				thePrimaryKey = entity.getKYCProfileId();

				KYCProfileService proxy = KYCProfileService.getKYCProfileInstance();            
				proxy.updateKYCProfile( entity );   

				LOGGER.info( "-- Successfully saved KYCProfile - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a KYCProfile.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created KYCProfile." );

			try{
			    KYCProfile entity = testRead(); 
				KYCProfileService.getKYCProfileInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted KYCProfile with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete KYCProfile with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all KYCProfiles.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of KYCProfiles:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all KYCProfile : " );        
			List<KYCProfile> collection  = null;

			try {
				// call the static get method on the KYCProfileService
				collection = KYCProfileService.getKYCProfileInstance().getAllKYCProfile();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					KYCProfile entity = null;            
					Iterator<KYCProfile> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getKYCProfileId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

